program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w)] for _ in range(h)]
    # The solid 2 line marks the edge toward which each row/column is packed.
    if all(v == 2 for v in grid[0]):
        out[0] = grid[0][:]
        for c in range(w):
            vals = [grid[r][c] for r in range(1, h) if grid[r][c] != 0]
            for i, v in enumerate(vals, 1):
                out[i][c] = v
    elif all(row[-1] == 2 for row in grid):
        for r in range(h):
            out[r][-1] = 2
            vals = [v for v in grid[r][:-1] if v != 0]
            for i, v in enumerate(reversed(vals), 1):
                out[r][w - 1 - i] = v
    elif all(row[0] == 2 for row in grid):
        for r in range(h):
            out[r][0] = 2
            vals = [v for v in grid[r][1:] if v != 0]
            for i, v in enumerate(vals, 1):
                out[r][i] = v
    else:
        barrier = next(r for r, row in enumerate(grid) if all(v == 2 for v in row))
        out[barrier] = grid[barrier][:]
        for c in range(w):
            vals = [grid[r][c] for r in range(barrier) if grid[r][c] != 0]
            for i, v in enumerate(vals):
                out[barrier - len(vals) + i][c] = v
    return out
'''
